using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;
public partial class TV {
 public static bool CanUseSharedAi(string url,string modelId){Uri u;return Uri.TryCreate(url,UriKind.Absolute,out u)&&u.Scheme=="https"&&u.Host=="openrouter.ai"&&u.Port==443&&u.AbsolutePath=="/api/v1/chat/completions"&&u.Query==""&&u.UserInfo==""&&u.Fragment==""&&modelId=="openrouter/free";}
 public static string SelectAiKey(string url,string modelId,string personal){if(!string.IsNullOrWhiteSpace(personal))return personal;if(!CanUseSharedAi(url,modelId))return "";using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("tvstudio.public-ai.json")){if(stream==null)return "";using(var reader=new StreamReader(stream)){var o=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(reader.ReadToEnd());return o.ContainsKey("key")?o["key"]:"";}}}
 public static object AiSchema(){return new JavaScriptSerializer().DeserializeObject("{\"type\":\"json_schema\",\"json_schema\":{\"name\":\"tv_app_advice\",\"strict\":true,\"schema\":{\"type\":\"object\",\"properties\":{\"suggestions\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"string\"},\"risk\":{\"type\":\"string\",\"enum\":[\"low\",\"unknown\",\"high\"]},\"reason\":{\"type\":\"string\"}},\"required\":[\"id\",\"risk\",\"reason\"],\"additionalProperties\":false}}},\"required\":[\"suggestions\"],\"additionalProperties\":false}}}");}
}
